import { useEffect, useRef, useState } from 'react';
import { useUiPref } from './useSettings';

/** The three stages of a quiet screen. */
export type IdlePhase = 'active' | 'ambient' | 'screensaver';

const ACTIVITY_EVENTS = ['pointermove', 'keydown', 'wheel'] as const;

/**
 * How long after a wake the click generated by the same tap is swallowed.
 * A tap on a sleeping screen must only wake it — never act on the UI that
 * appears under the finger (that was the tablet's "invisible misclick" bug).
 */
const WAKE_CLICK_GUARD_MS = 900;

/**
 * ONE idle timer for the whole app.
 *
 * Historically two independent timers existed — `useAmbientIdle` (ghost-faded the
 * cards) and `ScreensaverOverlay`'s own config timer — and they fought: the ghost
 * timer always fired first (2 min vs 5 min) so the screensaver never appeared on
 * its own. This hook replaces both with a single ladder:
 *
 *   active ──(ambientIdleMinutes)──▶ ambient ──(+screensaverMinutes)──▶ screensaver
 *
 * Any interaction drops straight back to `active`. The caller decides what each
 * phase *looks* like; this hook only owns the timing.
 *
 * Wake-on-touch is deliberately handled here, in the *capture* phase, and it
 * consumes the whole gesture: the contact that wakes the screen is swallowed
 * (`preventDefault` + `stopPropagation`) and so is the `click` the browser
 * synthesises afterwards. Without that guard the pointerdown woke React, the
 * ghosted UI became interactive again mid-gesture, and the tap landed on
 * whatever invisible card had just reappeared.
 */
export function useIdlePhase(): { phase: IdlePhase; wake: () => void } {
  const [enabled] = useUiPref('ambientIdleEnabled');
  const [minutes] = useUiPref('ambientIdleMinutes');
  const [screensaverMinutes] = useUiPref('screensaverMinutes');
  const [phase, setPhase] = useState<IdlePhase>('active');
  const phaseRef = useRef<IdlePhase>('active');
  const ambientTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const screensaverTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  /** Clicks ignored until this timestamp (the tap that woke the screen). */
  const muteClicksUntil = useRef(0);

  phaseRef.current = phase;

  useEffect(() => {
    const clearAll = () => {
      if (ambientTimer.current) clearTimeout(ambientTimer.current);
      if (screensaverTimer.current) clearTimeout(screensaverTimer.current);
      ambientTimer.current = null;
      screensaverTimer.current = null;
    };

    if (!enabled) {
      clearAll();
      setPhase('active');
      return;
    }

    const arm = () => {
      clearAll();
      const ambientMs = Math.max(0.5, minutes || 2) * 60 * 1000;
      const screensaverMs = Math.max(1, screensaverMinutes || 5) * 60 * 1000;
      ambientTimer.current = setTimeout(() => {
        setPhase('ambient');
        screensaverTimer.current = setTimeout(() => setPhase('screensaver'), screensaverMs);
      }, ambientMs);
    };

    // throttle so a pointer that never stops moving does not thrash timers
    let lastActivity = 0;
    const onActivity = () => {
      const now = Date.now();
      if (now - lastActivity < 500) return;
      lastActivity = now;
      // any interaction drops straight back to the live UI
      if (phaseRef.current !== 'active') setPhase('active');
      arm();
    };

    /**
     * First contact while asleep: wake, and eat the gesture so it cannot act on
     * the UI that is revealed underneath. Captured on `window` because the
     * sleeping UI has `pointer-events: none` — the wake layer (or the document)
     * is the only thing a finger can actually hit.
     */
    const onContact = (e: Event) => {
      if (phaseRef.current === 'active') return;
      e.preventDefault();
      e.stopPropagation();
      muteClicksUntil.current = Date.now() + WAKE_CLICK_GUARD_MS;
      lastActivity = Date.now();
      setPhase('active');
      arm();
    };

    /** Swallow the synthetic click/tap that follows the waking contact. */
    const onClickCapture = (e: Event) => {
      if (Date.now() < muteClicksUntil.current) {
        e.preventDefault();
        e.stopPropagation();
      }
    };

    ACTIVITY_EVENTS.forEach((ev) => window.addEventListener(ev, onActivity, { passive: true }));
    // non-passive: waking must be able to cancel the gesture outright
    window.addEventListener('pointerdown', onContact, { capture: true, passive: false });
    window.addEventListener('touchstart', onContact, { capture: true, passive: false });
    window.addEventListener('click', onClickCapture, true);
    arm();

    return () => {
      clearAll();
      ACTIVITY_EVENTS.forEach((ev) => window.removeEventListener(ev, onActivity));
      window.removeEventListener('pointerdown', onContact, { capture: true } as EventListenerOptions);
      window.removeEventListener('touchstart', onContact, { capture: true } as EventListenerOptions);
      window.removeEventListener('click', onClickCapture, true);
    };
  }, [enabled, minutes, screensaverMinutes]);

  const wake = () => setPhase('active');

  return { phase, wake };
}

export default useIdlePhase;
